# Credo over its defaults. Row modules are generated by Hireme.Schema and
# documented once there; decision tables stay one flat function.
%{
  configs: [
    %{
      name: "default",
      strict: true,
      files: %{included: ["lib/", "test/", "config/", "bench/"]},
      checks: %{
        extra: [
          {Credo.Check.Readability.LargeNumbers, only_greater_than: 99_999}
        ],
        disabled: [
          {Credo.Check.Refactor.CyclomaticComplexity, []},
          {Credo.Check.Refactor.Nesting, []}
        ]
      }
    }
  ]
}
